questionvariables.text:
ev_val: 2000 + rand(1000);
ta_val: 1000 + rand(1000);

ta_E: stackunits(ev_val, mV);
ta_tau: stackunits(ta_val, us);

tau_unit: stack_units_units(ta_tau);
E_unit: stack_units_units(ta_E);

precision_q: 0.1;

feedbackvariables.text:
stud_si_tau : stack_unit_si_to_si_base(ans_tau);
teach_si_tau : stack_unit_si_to_si_base(tau_unit);
v_pure_e_tau : subst(map(lambda([u], u=1), listofvars(stud_si_tau)), stud_si_tau);
v_pure_t_tau : subst(map(lambda([u], u=1), listofvars(teach_si_tau)), teach_si_tau);
eleve_unit_tau : 2 * stud_si_tau / v_pure_e_tau;
teacher_unit_tau : 2 * teach_si_tau / v_pure_t_tau;

/* --- Traitement E --- */
stud_si_E : stack_unit_si_to_si_base(ans_E);
teach_si_E : stack_unit_si_to_si_base(E_unit);
v_pure_e_E : subst(map(lambda([u], u=1), listofvars(stud_si_E)), stud_si_E);
v_pure_t_E : subst(map(lambda([u], u=1), listofvars(teach_si_E)), teach_si_E);
eleve_unit_E : 2 * stud_si_E / v_pure_e_E;
teacher_unit_E : 2 * teach_si_E / v_pure_t_E;
